// 黄金矿工 - 原始代码（包含Bug）
class GoldMiner {
  constructor() {
    this.score = 0;
    this.time = 60;
    this.hookAngle = 0;
    this.hookLength = 0;
    this.isShooting = false;
    this.isRetracting = false;
    this.items = [];
    this.hookSpeed = 5;
  }

  launchHook() {
    if (this.isShooting || this.isRetracting) return;
    this.isShooting = true;
    this.hookSpeed = 5;
  }

  update() {
    if (this.isShooting) {
      this.hookLength += this.hookSpeed;

      // Bug 1: 最大长度检查错误 - 应该用 >= 而不是 >
      if (this.hookLength > 300) {
        this.isShooting = false;
        this.isRetracting = true;
      }

      // Bug 2: 碰撞检测只在伸展时进行
      for (let item of this.items) {
        if (this.checkCollision(item)) {
          this.catchItem(item);
        }
      }
    }

    if (this.isRetracting) {
      // Bug 3: 收回速度不考虑物品重量
      this.hookLength -= this.hookSpeed;

      if (this.hookLength <= 0) {
        this.hookLength = 0;
        this.isRetracting = false;
        this.score += this.caughtItemValue; // Bug 4: 可能为undefined
      }
    }
  }

  checkCollision(item) {
    // Bug 5: 钩子末端位置计算错误
    let hookX = 400 + this.hookLength;
    let hookY = 300;

    // Bug 6: 没有考虑钩子角度
    let dx = hookX - item.x;
    let dy = hookY - item.y;
    let distance = Math.sqrt(dx * dx + dy * dy);

    return distance < item.radius + 10;
  }

  catchItem(item) {
    this.caughtItemValue = item.value;
    item.isCaught = true;
    // Bug 7: 没有停止伸展就直接设置收回
    this.isRetracting = true;
    this.isShooting = false;
  }

  checkTimeOut() {
    // Bug 8: 时间递减逻辑错误
    this.time -= 1; // 应该是 deltaTime
  }

  addItem(item) {
    // Bug 9: 没有检查重复添加
    this.items.push(item);
  }

  removeItem(itemId) {
    // Bug 10: 使用==而非===
    this.items = this.items.filter(item => item.id == itemId);
  }

  getScore() {
    return this.score;
  }

  getTime() {
    return this.time;
  }
}

